SELECT (t."审核状态").name AS "审核状态",t."有效期" AS "有效期",COUNT(t.rec_id) AS total,s."国家" AS supplier_country,(s."推广阶段").name AS supplier_stage FROM "SupplierQualifications" AS t LEFT JOIN "Suppliers" AS s ON t."供应商" @> ARRAY[s.rec_id] INNER JOIN "Members" AS access_member ON (access_member."用户").id = CURRENT_USER_ID() LEFT JOIN "Roles" AS access_role ON access_member."角色编码" = access_role."角色编码" WHERE (access_member."状态").name = '启用' AND (((access_member."角色编码" IS NULL AND (access_member."角色").name IN ('管理员','采购','中央仓','技术','只读')) OR (access_role."启用" = TRUE AND access_role."权限代码" LIKE '%|dashboard.view|%')) OR ((access_member."角色编码" IS NULL AND (access_member."角色").name IN ('管理员','采购','中央仓','技术','只读')) OR (access_role."启用" = TRUE AND access_role."权限代码" LIKE '%|reports.view|%'))) GROUP BY (t."审核状态").name,t."有效期",s."国家",(s."推广阶段").name LIMIT 10000